/// ソート済み配列でx以上の要素の位置を返す
/// 存在しない場合は None
#[inline(always)]
pub fn lower_bound<T: Ord>(arr: &[T], x: &T) -> Option<usize> {
    let mut left = 0_usize;
    let mut right = arr.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < *x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return if left < arr.len() { Some(left) } else { None };
} // end of method

/// ソート済み配列でxより大きい要素の位置を返す
/// 存在しない場合は None
#[inline(always)]
pub fn upper_bound<T: Ord>(arr: &[T], x: &T) -> Option<usize> {
    let mut left = 0_usize;
    let mut right = arr.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] <= *x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return if left < arr.len() { Some(left) } else { None };
} // end of method

/// ソート済み配列でx未満の最大値のindexを返す
/// 存在しない場合はNone
#[inline(always)]
pub fn less_than_max<T: Ord>(arr: &[T], x: &T) -> Option<usize> {
    if arr.is_empty() {
        return None;
    }

    // x以上の位置を出して, ここからずらす
    let index = lower_bound(arr, x);

    if let Some(i) = index {
        // これより小さい値は無い
        if i == 0 {
            return None;
        }

        // iの1つ左がLess Than Max
        return Some(i - 1);
    }

    // lower_boundがNoneの場合, 最後の要素がLess Than Max
    return Some(arr.len() - 1);
} // end of method

/// ソート済み配列でx以下の最大値のindexを返す
/// 存在しない場合はNone
pub fn less_than_or_equal_max<T: Ord>(arr: &[T], x: &T) -> Option<usize> {
    if arr.is_empty() {
        return None;
    }

    // x超過の位置を出して、ここからずらす
    let index = upper_bound(arr, x);

    if let Some(i) = index {
        // これ以下の値は無い
        if i == 0 {
            return None;
        }

        // iの1つ左が欲しいやつ
        return Some(i - 1);
    }

    // upper_boundがNoneの場合, 最後の要素が欲しいやつ
    return Some(arr.len() - 1);
} // end of method
